#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.17799536999999999, 0.35477422000000003, -0.04627351], 'basis': [[0.0, 0.9855239852128891, -0.16953605684368556], [-0.988609721764247, 0.025515496493540075, 0.14832321959796538], [0.15050188714171697, 0.16760499398524353, 0.9742985928133061]], 'axis': [-0.16953605684368556, 0.14832321959796538, 0.9742985928133061], 'zmin': -0.024033641017726027, 'zmax': 0.02337528915724315, 'profiles': [{'outer': [[-0.1436475613681427, 0.10665963650621248], [-0.14382321513066354, 0.108842366688667], [-0.14380794069413752, 0.11065575061879318], [-0.14369338467772075, 0.11240258016467922], [-0.14337262903576883, 0.11435377312574364], [-0.1419954454302156, 0.11890726225242104], [-0.13992071889774033, 0.12274687228777142], [-0.13953123355898742, 0.12333243889767784], [-0.13658083027140624, 0.12682455853584784], [-0.13298633786399844, 0.12966755513442754], [-0.1289094750363938, 0.13174694366278233], [-0.12382323950346148, 0.1330906597232638], [-0.11921179145620854, 0.13341915565070686], [-0.114630849727581, 0.13285340898221792], [-0.110293054915313, 0.13139016020859587], [-0.10630018934497594, 0.1291001215220895], [-0.10283555704880257, 0.12605510761228897], [-0.09966365004086863, 0.12195051719823706], [-0.09752785843061865, 0.117306340320065], [-0.09650832978053511, 0.11279123859573476], [-0.09633267752303315, 0.11058325761272914], [-0.0963479549695969, 0.1087951785864433], [-0.09666106963073863, 0.10561271561276556], [-0.09787152346983127, 0.10126219617520836], [-0.09813118136567914, 0.1005428986878393], [-0.10020587974488168, 0.09667795824455415], [-0.10059536658865348, 0.09611770806977794], [-0.10354579953452628, 0.09262559905231264], [-0.10713262130283226, 0.08979111099381264], [-0.11121713499734427, 0.08770320355982834], [-0.11561602755571633, 0.0864670525143339], [-0.12091484673080226, 0.08600565619175887], [-0.12549574891504092, 0.08659671009556824], [-0.12603499852913294, 0.08677861303685716], [-0.12728895786684893, 0.08380624014274655], [-0.1300773273049648, 0.07177701146884292], [-0.13078935724098592, 0.05956018064505625], [-0.12956058264815598, 0.04713864949137513], [-0.12644623797077484, 0.034554973985270784], [-0.12154540126558526, 0.02191640124736139], [-0.11489438567268655, 0.009286536256002844], [-0.10663812288230816, -0.003237001078237408], [-0.09685855464880302, -0.015600200654494129], [-0.08561863823971831, -0.027728011861301922], [-0.0730727667498933, -0.039533320416080965], [-0.05932969111474383, -0.050888082122061265], [-0.044425590584064645, -0.061791271519027385], [-0.028505372560834265, -0.07211400335776105], [-0.01167781828779501, -0.08179077616039365], [0.0059484597049983615, -0.09075614978586542], [0.02429152202419586, -0.09895621146587445], [0.04320638754908186, -0.1062619017989502], [0.06265689293603423, -0.11264099704170043], [0.08246176133542975, -0.11802619319536294], [0.10254870108935632, -0.12232167959347351], [0.12283569823074283, -0.12547348712214143], [0.1432234952480777, -0.12740565613053972], [0.14279500445730336, -0.13391788775513178], [0.12203543883950774, -0.13198690469733565], [0.10137666622160096, -0.12877363960751492], [0.08091800729769977, -0.12441671038652102], [0.06075074573761603, -0.11892820933974864], [0.04100095661500261, -0.11242690089004302], [0.021759968515101008, -0.10498753340646341], [0.0031176041930669504, -0.09669659599586895], [-0.014798504511855997, -0.08756714223103983], [-0.031915948813608215, -0.07769501708206929], [-0.04812599604394931, -0.06717694260711739], [-0.06332941985467834, -0.056088879367596246], [-0.07739859528261128, -0.044443887184271086], [-0.09027053003086857, -0.03234833281438718], [-0.10183658191110379, -0.019867627598749722], [-0.11194224155631399, -0.0070889492330723294], [-0.1205513615290498, 0.005955481945447827], [-0.12748277458274124, 0.01919833563524823], [-0.1327002496761045, 0.03257607453379175], [-0.1360130964803738, 0.04603188351164882], [-0.13735838588127466, 0.05942816319152735], [-0.13654555606930516, 0.07273939214754283], [-0.1335020598530445, 0.08583848072710124], [-0.13204074508731706, 0.08932589186516908], [-0.13382641080266494, 0.09035005501108581], [-0.13729107426214882, 0.09339503844458176], [-0.1404553121359998, 0.09750810615694386], [-0.14259113490956027, 0.1021522919797708]], 'holes': []}], 'simplify_tolerance': 5.741086906789519e-05, 'sketch_entity_count': 85}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
